def caesar(s, k):
    """Shift letters."""
    res = []
    for c in s:
        if c.isalpha():
            base = ord('a') if c.islower() else ord('A')
            res.append(chr((ord(c) - base + k) % 26 + base))
        else:
            res.append(c)
    return "".join(res)

